def hex_key(num: str) -> int:
    """Counts the number of hexadecimal digits that are prime numbers."""

    def is_prime(n: int) -> bool:
        """Checks if a number is prime."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # Convert hexadecimal to decimal and count prime digits
    prime_count = 0
    for digit in num:
        if digit in '2345677':
            prime_count += 1
        elif digit in 'ABD':
            prime_count += 1 if is_prime(int(digit, 16)) else 0

    return prime_count
```

