def is_equal_to_sum_even(n: int) -> bool:
    """
    Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers.

    Args:
        n (int): The number to evaluate.

    Returns:
        bool: True if n can be written as the sum of exactly 4 positive even numbers, False otherwise.

    Example:
        is_equal_to_sum_even(4) == False
        is_equal_to_sum_even(6) == False
        is_equal_to_sum_even(8) == True
    """
    def can_be_sum_of_four_even_numbers(num: int) -> bool:
        for i in range(2, num, 2):
            for j in range(i, num, 2):
                for k in range(j, num, 2):
                    for last in range(k, num, 2):
                        if i + j + k + last == num:
                            return True
        return False

    return can_be_sum_of_four_even_numbers(n)
```

