def comb_sort(lst):
    def is_sorted(lst):
        return all(lst[i] <= lst[i+1] for i in range(len(lst)-1))

    if is_sorted(lst):
        return lst

    gap = len(lst) // 2
    while gap > 0:
        for i in range(gap, len(lst)):
            temp = lst[i]
            j = i
            while j >= gap and lst[j-gap] > temp:
                lst[j] = lst[j-gap]
                j -= gap
            lst[j] = temp
        gap //= 2

    return lst

