def pancake_sort(lst):
    n = len(lst)
    for i in range(n - 1, -1, -1):
        max_idx = lst.index(max(lst[:i + 1]))
        if max_idx != i:
            if max_idx > i:
                lst = lst[:max_idx] + lst[max_idx + 1:] + [lst[max_idx]]
            else:
                lst = lst[:i] + lst[i + 1:] + [lst[i]]
            lst = lst[:i + 1] + lst[i + 1:][::-1]
    return lst

