def is_majority(arr, n, target):
    left, right = 0, n - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            # Check if the target is the majority element
            count = 0
            for i in range(n):
                if arr[i] == target:
                    count += 1
            return count > n / 2
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return False

